const n3=node({type:"n8n-nodes-base.code",version:2,config:{"name":"Validar itinerário","parameters":{"mode":"runOnceForAllItems","language":"javaScript","jsCode":"const fail = (message) => { throw new Error('Itinerário inválido: ' + message); };\nconst record = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);\nconst textField = (value, path, max, empty = false) => {\n  if (typeof value !== 'string' || (!empty && !value.trim()) || value.length > max) {\n    fail(path + ' deve ser texto válido de até ' + max + ' caracteres.');\n  }\n};\nconst requestedDays = $('Webhook').first().json.body?.dias;\nif (!Number.isInteger(requestedDays) || requestedDays < 1 || requestedDays > 7) {\n  fail('dias solicitado deve ser inteiro entre 1 e 7.');\n}\nlet itinerary = $input.first().json.output;\nif (typeof itinerary === 'string') {\n  if (itinerary.length > 250000) fail('resposta excede 250000 caracteres.');\n  let raw = itinerary.trim();\n  if (!raw.startsWith('{')) {\n    const fences = [...raw.matchAll(/```(?:json)?\\s*([\\s\\S]*?)\\s*```/gi)];\n    if (fences.length === 1) {\n      const outside = raw.slice(0, fences[0].index) + raw.slice(fences[0].index + fences[0][0].length);\n      if (/[{}\\[\\]]/.test(outside) || outside.includes('```')) fail('output contém conteúdo JSON ambíguo.');\n      raw = fences[0][1].trim();\n    }\n  }\n  try { itinerary = JSON.parse(raw); }\n  catch { fail('output não contém JSON válido.'); }\n}\nif (!record(itinerary)) fail('output deve conter um objeto JSON.');\ntextField(itinerary.titulo, 'titulo', 180);\ntextField(itinerary.descricao_geral, 'descricao_geral', 2500);\ntextField(itinerary.fonte, 'fonte', 500, true);\nif (!Array.isArray(itinerary.dias) || itinerary.dias.length !== requestedDays) {\n  fail('esperados exatamente ' + requestedDays + ' dias.');\n}\nlet expectedOrder = 1;\nconst periods = ['manha', 'tarde', 'noite'];\nitinerary.dias.forEach((day, dayIndex) => {\n  const path = 'dias[' + dayIndex + ']';\n  if (!record(day) || day.dia !== dayIndex + 1) fail(path + '.dia deve seguir a sequência de 1 até N.');\n  if (!Array.isArray(day.locais) || day.locais.length > 20) fail(path + '.locais deve ser array com até 20 locais.');\n  let previousPeriod = -1;\n  day.locais.forEach((place, placeIndex) => {\n    const localPath = path + '.locais[' + placeIndex + ']';\n    if (!record(place)) fail(localPath + ' deve ser objeto.');\n    if (place.ordem !== expectedOrder) fail(localPath + '.ordem deve ser ' + expectedOrder + ' (sequência global).');\n    const period = periods.indexOf(place.periodo);\n    if (period < 0 || period < previousPeriod) fail(localPath + '.periodo deve respeitar manha, tarde, noite.');\n    textField(place.nome, localPath + '.nome', 120);\n    textField(place.descricao_curta, localPath + '.descricao_curta', 1200);\n    textField(place.duracao_estimada, localPath + '.duracao_estimada', 80);\n    if (!Number.isFinite(place.latitude) || Math.abs(place.latitude) > 90) fail(localPath + '.latitude inválida.');\n    if (!Number.isFinite(place.longitude) || Math.abs(place.longitude) > 180) fail(localPath + '.longitude inválida.');\n    expectedOrder++;\n    previousPeriod = period;\n  });\n});\nif (expectedOrder === 1) fail('nenhum local retornado nas bases permitidas.');\nreturn [{ json: itinerary }];"},"position":[560,0],"onError":"continueErrorOutput","executeOnce":undefined},output:[{"titulo":"Exemplo","descricao_geral":"Resumo","dias":[],"fonte":"base_Florianopolis"}]});
